# Settings that become per person. Existing values move to the first (admin) account.
USER_KEYS = [
    "province", "target_basis", "quiet_hours_enabled", "quiet_hours_start", "quiet_hours_end",
    "target_bypasses_quiet_hours", "notify_urls", "alert_target", "alert_drop", "alert_drop_pct",
    "alert_all_time_low", "alert_back_in_stock", "alert_source_failing", "alert_domain_blocked",
    "digest_enabled", "digest_time", "digest_time_blackfriday", "my_best_buy_member",
]


def _migrate_existing_data() -> None:
    import hashlib
    import json

    conn = op.get_bind()
    has_items = conn.execute(sa.text("SELECT COUNT(*) FROM items")).scalar()
    has_settings = conn.execute(sa.text("SELECT COUNT(*) FROM settings")).scalar()
    if not has_items and not has_settings:
        return  # fresh install: the app creates the admin on first start
    # admin with no password yet; startup sets it from PRICEWATCH_ADMIN_PASSWORD
    conn.execute(sa.text(
        "INSERT INTO users (username, display_name, role, active, created_at) "
        "VALUES ('admin', 'Admin', 'admin', 1, CURRENT_TIMESTAMP)"))
    uid = conn.execute(sa.text("SELECT id FROM users WHERE username = 'admin'")).scalar()
    conn.execute(sa.text("INSERT INTO lists (name, owner_id, created_at) VALUES ('My list', :u, CURRENT_TIMESTAMP)"),
                 {"u": uid})
    lid = conn.execute(sa.text("SELECT MAX(id) FROM lists")).scalar()
    conn.execute(sa.text("INSERT INTO list_members (list_id, user_id, role, joined_at) "
                         "VALUES (:l, :u, 'owner', CURRENT_TIMESTAMP)"), {"l": lid, "u": uid})
    conn.execute(sa.text("UPDATE items SET list_id = :l, added_by = :u WHERE list_id IS NULL"), {"l": lid, "u": uid})
    conn.execute(sa.text("UPDATE alerts SET user_id = :u WHERE user_id IS NULL"), {"u": uid})
    for row in conn.execute(sa.text("SELECT key, value FROM settings")).fetchall():
        key, value = row[0], row[1]
        if key in USER_KEYS:
            conn.execute(sa.text("INSERT INTO user_settings (user_id, key, value) VALUES (:u, :k, :v)"),
                         {"u": uid, "k": key, "v": value})
            conn.execute(sa.text("DELETE FROM settings WHERE key = :k"), {"k": key})
        elif key == "api_token" and value:
            token = json.loads(value) if isinstance(value, str) else value
            if token:
                conn.execute(sa.text("UPDATE users SET api_token_hash = :h WHERE id = :u"),
                             {"h": hashlib.sha256(str(token).encode()).hexdigest(), "u": uid})
    for row in conn.execute(sa.text("SELECT id, snoozed_until FROM items WHERE snoozed_until IS NOT NULL")).fetchall():
        conn.execute(sa.text("INSERT INTO user_item_prefs (user_id, item_id, snoozed_until, muted) "
                             "VALUES (:u, :i, :s, 0)"), {"u": uid, "i": row[0], "s": row[1]})


